/** Real browser + authenticated Host API checks; only use the isolated fixture. */
import * as fs from 'node:fs'
import * as path from 'node:path'
import { pathToFileURL } from 'node:url'
import assert from 'node:assert/strict'
const runtimePath = path.resolve(process.argv[2])
const runtime = JSON.parse(fs.readFileSync(runtimePath, 'utf8'))
const evidence = path.dirname(runtimePath)
// A separate synthetic book exercises the viewport budget and long Chinese labels.
const stress = path.join(runtime.workspace, '图谱压力样本')
fs.mkdirSync(path.join(stress, '作品契约'), { recursive: true })
fs.mkdirSync(path.join(stress, '世界书', '人物档案'), { recursive: true })
fs.writeFileSync(path.join(stress, '作品契约', '契约.md'), '---\n书id: visual-stress\n---\n图谱压力样本')
for (let i = 1; i <= 185; i++) fs.writeFileSync(path.join(stress, '世界书', '人物档案', `${i}.md`), `---\n名称: 测试人物${i}与一段很长的中文名字\n起始章: 1\n披露章: 1\n---\n合成图谱样本。`)
const { chromium } = await import(pathToFileURL(path.join(process.env.WEBNOVEL_PLAYWRIGHT, 'index.mjs')).href)
const browser = await chromium.launch({ headless: true, executablePath: process.env.WEBNOVEL_CHROMIUM })
const page = await browser.newPage({ viewport: { width: 1500, height: 1000 } })
page.setDefaultTimeout(15000)
const report = { checks: [], errors: [] }
page.on('pageerror', e => report.errors.push(e.message))
const save = () => fs.writeFileSync(path.join(evidence, 'visualization-report.json'), JSON.stringify(report, null, 2))
const capture = name => page.screenshot({ path: path.join(evidence, name + '.png'), fullPage: true })
try {
  let url
  for (let i = 0; i < 120 && !url; i++) {
    url = fs.readFileSync(path.join(runtime.root, 'stdout.log'), 'utf8').match(/dsh web: (http\S+)/)?.[1]
    if (!url) await new Promise(resolve => setTimeout(resolve, 250))
  }
  assert.ok(url)
  await page.goto(url)
  await page.getByRole('tab', { name: '书房', exact: true }).waitFor({ timeout: 30000 })
  const welcome = page.getByRole('button', { name: '继续', exact: true })
  await welcome.waitFor({ timeout: 5000 }).catch(() => {})
  if (await welcome.isVisible()) await welcome.click()
  await page.getByRole('tab', { name: '工作区', exact: true }).click()
  const workspace = page.getByRole('treeitem', { name: /^S5 临时验收书房/ }).first()
  await workspace.waitFor()
  if (await workspace.getAttribute('aria-expanded') === 'false') await workspace.click()
  await page.getByText('S5 书房验收', { exact: true }).first().click()
  await page.getByRole('tab', { name: '可视化', exact: true }).click()
  await page.getByRole('heading', { name: '写作流程', exact: true }).waitFor()
  await page.getByLabel('选择可视化作品', { exact: true }).selectOption('book:acceptance-a')
  await page.locator('.nw-archify [data-node-id="concept"]').waitFor()
  await capture('workflow-idle')
  report.checks.push('中文流程初始视图'); save()
  await page.getByRole('button', { name: '人物关系', exact: true }).click()
  await page.getByRole('slider', { name: '图谱章节时间线' }).fill('4')
  const person = await page.getByLabel('选择图谱记录').locator('option').filter({ hasText: '人物：林舟' }).first().getAttribute('value')
  await page.getByLabel('选择图谱记录').selectOption(person)
  await page.getByRole('button', { name: '直接关联', exact: true }).click()
  await capture('relationships')
  await page.getByRole('button', { name: '清除筛选', exact: true }).click()
  await page.getByLabel('关系终点', { exact: true }).selectOption({ label: '沈青 · 人物' })
  await page.locator('.nw-inspector [role="status"]').filter({ hasText: '林舟 → 沈青' }).waitFor()
  report.checks.push('真实图谱、章节筛选、节点详情与关系路径'); save()
  const lightFill = await page.locator('.nw-g6-canvas').evaluate(el => [...el.querySelectorAll('canvas')].map(c => c.toDataURL()).join('|'))
  await page.emulateMedia({ colorScheme: 'dark' })
  await page.waitForFunction(previous => [...document.querySelectorAll('.nw-g6-canvas canvas')].map(c => c.toDataURL()).join('|') !== previous, lightFill)
  await capture('relationships-dark')
  await page.emulateMedia({ colorScheme: 'light' })
  report.checks.push('宿主深浅主题切换')
  await page.getByRole('button', { name: '关闭详情', exact: true }).click()
  await page.getByRole('button', { name: '查看全图', exact: true }).click()
  await page.getByRole('button', { name: '全屏', exact: true }).click()
  await page.waitForFunction(() => !!document.fullscreenElement)
  await page.getByRole('button', { name: '退出全屏', exact: true }).click()
  await page.getByRole('textbox', { name: '搜索图谱' }).fill('林舟')
  await page.locator('.nw-map-search-results button').first().click()
  await page.getByRole('button', { name: '关闭详情', exact: true }).click()
  await page.getByRole('textbox', { name: '搜索图谱' }).fill('')
  report.checks.push('搜索定位与全屏退出')
  await page.setViewportSize({ width: 720, height: 960 })
  await capture('relationships-narrow')
  assert.equal(await page.evaluate(() => document.documentElement.scrollWidth > innerWidth + 1), false)
  report.checks.push('窄窗口无横向溢出')
  await page.setViewportSize({ width: 1500, height: 1000 })
  await page.getByRole('button', { name: '写作流程', exact: true }).click()
  const api = async (method, body) => page.evaluate(async ({ method, body }) => {
    const response = await fetch(method, { method: 'POST', headers: { 'content-type': 'application/json', 'x-webnovel-request': '1' }, body: JSON.stringify(body) })
    return { status: response.status, data: await response.json() }
  }, { method, body })
  const read = () => api('/api/webnovel/study/workflow', { sessionId: 'webnovel-browser-acceptance', space: 'book:acceptance-a' })
  assert.equal((await api('/api/webnovel-workflow-check', { action: 'run' })).status, 200)
  await page.locator('.nw-flow-summary').filter({ hasText: '备料 · 进行中' }).waitFor()
  await capture('workflow-running')
  const current = await read()
  assert.equal(current.data.value.calls.at(-1).state, 'running')
  await page.locator('.nw-flow-summary').filter({ hasText: '当前没有执行中的操作' }).waitFor()
  const ended = await read()
  assert.ok(ended.data.value.calls.at(-1).ended !== undefined)
  report.checks.push('真实工具管线开始/结束与HTTP状态一致'); report.lastResult = ended.data.value.calls.at(-1)
  assert.equal((await api('/api/webnovel-workflow-check', { action: 'waiting' })).status, 200)
  await page.locator('.nw-flow-summary').filter({ hasText: '待确认' }).waitFor()
  await capture('workflow-waiting')
  assert.equal((await read()).data.value.calls.at(-1).state, 'waiting')
  await api('/api/webnovel-workflow-check', { action: 'cancel' })
  await page.locator('.nw-flow-summary').filter({ hasText: '当前没有执行中的操作' }).waitFor()
  report.cancelled = (await read()).data.value.calls.at(-1); save()
  assert.equal(report.cancelled.state, 'stopped')
  report.checks.push('真实待答与取消，停止后无假运行')
  const other = await api('/api/webnovel/study/workflow', { sessionId: 'webnovel-browser-acceptance', space: 'book:acceptance-b' })
  assert.equal(other.data.value.calls.length, 0)
  assert.equal((await api('/api/webnovel/study/workflow', { sessionId: 'webnovel-browser-acceptance', space: 'book:missing' })).status, 404)
  report.checks.push('API书身份与未知书保护')
  await page.reload()
  await page.getByRole('tab', { name: '可视化', exact: true }).click()
  await page.getByLabel('选择可视化作品', { exact: true }).selectOption('book:acceptance-a')
  await page.locator('.nw-flow-summary').filter({ hasText: '当前没有执行中的操作' }).waitFor()
  report.checks.push('刷新后历史调用不恢复为运行中')
  await page.locator('.nw-archify [data-node-id="materials"]').click()
  await capture('workflow-complete')
  await page.route('**/api/webnovel/study/workflow', route => route.abort())
  await page.locator('.nw-flow-summary').filter({ hasText: '连接已断' }).waitFor()
  await page.unroute('**/api/webnovel/study/workflow')
  await page.locator('.nw-flow-summary').filter({ hasText: '当前没有执行中的操作' }).waitFor()
  report.checks.push('断线提示与重连快照恢复')
  await page.getByLabel('选择可视化作品', { exact: true }).selectOption('book:visual-stress')
  await page.getByRole('button', { name: '人物关系', exact: true }).click()
  await page.waitForFunction(() => document.querySelectorAll('[aria-label="选择图谱记录"] optgroup[label="人物与条目"] option').length === 180)
  await page.getByRole('textbox', { name: '搜索图谱' }).fill('测试人物185')
  await page.locator('.nw-map-search-results button').first().click()
  await capture('large-graph-search')
  assert.equal(await page.locator('[aria-label="选择图谱记录"] optgroup[label="人物与条目"] option').count(), 1)
  report.checks.push('185条真实合成记录、180节点上限及范围外搜索定位')
  const sourceResponse = page.waitForResponse(r => r.url().endsWith('/api/webnovel/study/read') && r.request().postDataJSON()?.ref?.path === '世界书/人物档案/185.md')
  await page.locator('.nw-inspector .nw-source-button').click()
  const source = await sourceResponse; assert.equal(source.status(), 200)
  const sourceDocument = await source.json(); assert.equal(sourceDocument.value.ref.path, '世界书/人物档案/185.md')
  report.checks.push('来源按钮沿现有编辑器读取真实书仓原文')
  assert.deepEqual(report.errors, [])
  report.passed = true
} catch (error) { report.failure = String(error); await capture('failure'); throw error }
finally { save(); await browser.close() }
